import {bodyCluesPage,bindBodyClues} from './body-clues-ui.mjs';
import {cellCases,cellSource} from './cell-studio-content.mjs';
import {newCellWork,changeCellWork,cellModelsView,lastCellModel,keepCellModel} from './cell-studio-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>structuredClone(x);
const button=(attrs,label,on=false)=>`<button type="button" class="${on?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
let visit=null;
export function resetCellStudio(){visit=null;}
function state(book,owner){if(!visit||visit.book!==book||visit.owner!==owner)visit={book,owner,mode:'legacy',screen:'draft',active:'leaf',slots:new Map(),copies:new Map(),readonly:new Map(),card:null,shelfPage:null,chooser:false};return visit;}
function makeSlot(source,work){return {source:clone(source),work:clone(work||newCellWork(source)),turn:0,role:null,status:''};}
const slot=v=>v.screen==='card'?v.readonly.get(v.card):v.slots.get(v.active)||v.copies.get(v.active);
function draft(v,id){if(!v.slots.has(id))v.slots.set(id,makeSlot(cellSource(id)));v.active=id;v.screen='draft';}
function drawing(source,ids,reference=false){const selected=new Set(ids),parts=source.parts.filter(p=>selected.has(p.id));const plant=source.outline==='plant';const outside=plant?'M60 42H480Q510 42 510 72V328Q510 358 480 358H60Q30 358 30 328V72Q30 42 60 42Z':'M95 47Q210 12 326 45Q474 24 505 155Q541 265 438 345Q320 384 199 349Q50 375 32 267Q2 158 95 47Z';const inside=plant?'M68 57H472Q495 57 495 80V320Q495 343 472 343H68Q45 343 45 320V80Q45 57 68 57Z':'M104 62Q210 28 324 60Q459 40 490 161Q523 259 429 330Q320 366 202 334Q64 358 48 263Q19 162 104 62Z';const has=s=>parts.some(p=>p.symbol===s);const n=s=>source.parts.findIndex(p=>p.symbol===s)+1;const mark=(s,x,y)=>`<text x="${x}" y="${y}" class="cs-number">${n(s)}</text>`;const symbols={wall:`<path d="${outside}" class="cs-wall"/>${mark('wall',490,47)}`,membrane:`<path d="${inside}" class="cs-membrane"/>${mark('membrane',468,81)}`,cytoplasm:`<path d="${inside}" class="cs-cytoplasm"/>${mark('cytoplasm',84,309)}`,nucleus:`<ellipse cx="140" cy="151" rx="48" ry="43" class="cs-nucleus"/><circle cx="128" cy="144" r="10" class="cs-nucleus-center"/>${mark('nucleus',151,163)}`,vacuole:`<ellipse cx="352" cy="225" rx="104" ry="91" class="cs-vacuole"/>${mark('vacuole',352,231)}`,mitochondria:`<path d="M113 239C84 217 70 263 101 278C130 300 162 277 151 255C145 242 128 249 113 239Z" class="cs-mito"/><path d="m100 249 10 15 10-12 11 15 10-6" class="cs-fold"/>${mark('mitochondria',174,270)}`,ribosomes:`<g class="cs-ribosome"><circle cx="191" cy="184" r="5"/><circle cx="213" cy="199" r="5"/><circle cx="190" cy="218" r="5"/></g>${mark('ribosomes',220,228)}`,chloroplasts:`<ellipse cx="325" cy="97" rx="47" ry="23" class="cs-chloroplast"/><path d="M299 89v16m12-16v16m12-16v16m12-16v16m12-16v16" class="cs-fold"/>${mark('chloroplasts',390,105)}`};return `<figure class="cs-drawing" ${reference?'data-cs-source':'data-cs-model'}><figcaption>${reference?'Source reference drawing':'My illustration'}</figcaption><svg viewBox="0 0 540 400" role="img" aria-label="${esc((reference?'Source reference. ':'My illustration. ')+(parts.map(p=>p.label).join(', ')||'No parts selected.'))}">${!has('membrane')&&!has('wall')?`<path d="${outside}" class="cs-guide"/>`:''}${['cytoplasm','wall','membrane','vacuole','nucleus','mitochondria','ribosomes','chloroplasts'].map(s=>has(s)?`<g data-cs-symbol="${s}">${symbols[s]}</g>`:'').join('')}</svg><p class="cs-guide-note">${!has('membrane')&&!has('wall')?'Dashed line: layout guide only, not a cell part. ':''}Shape does not identify every plant or animal cell.</p>${parts.length?`<ol class="cs-legend">${parts.map(p=>`<li value="${source.parts.indexOf(p)+1}">${esc(p.label)}</li>`).join('')}</ol>`:'<p>No parts selected. This empty layout is not a biological cell.</p>'}</figure>`;}
function comparison(s){return `<section class="cs-comparison"><h3>Compare with source drawing</h3><p>The source is separate from your illustration. These are part choices, not a score or a newly discovered cell.</p><div class="cs-table-wrap"><table data-cs-comparison><caption>Parts in each drawing</caption><thead><tr><th>Part</th><th>My drawing</th><th>This source example</th></tr></thead><tbody>${s.source.parts.map(p=>`<tr><th scope="row">${esc(p.label)}</th><td>${s.work.selectedIds.includes(p.id)?'In my drawing':'Not in my drawing'}</td><td>${p.present?'In this source example':'Not in this source example'}</td></tr>`).join('')}</tbody></table></div></section>`;}
function teaching(s,readonly){return `<section class="cs-teaching"><h3>Look at the source example</h3><p>Look closely at the source. Your drawing stays as you made it.</p>${s.work.exampleSeen?`${drawing(s.source,s.source.parts.filter(p=>p.present).map(p=>p.id),true)}${s.source.teaching.slice(0,s.work.exampleSeen).map(t=>`<p>${esc(t)}</p>`).join('')}`:''}${readonly?'':button(`data-cs-example${s.work.exampleSeen>=s.source.teaching.length?' disabled':''}`,s.work.exampleSeen===0?'Show part of the explanation':s.work.exampleSeen>=s.source.teaching.length?'Explanation shown':'Next part')}</section>`;}
function activePage(s,readonly=false){const role=s.source.parts.find(p=>p.id===s.role);return `<h2 id="cs-title" tabindex="-1">${esc(s.source.title)}</h2><p>${esc(s.source.context)}</p><p>${esc(s.source.job)}</p>${readonly?'<p class="cs-notice">Kept sheet · this illustration and its shown help stay unchanged. Work on a copy to change parts or reveal more.</p>':''}<nav class="cs-actions" aria-label="Illustration turns">${['Build','Compare'].map((t,i)=>button(`data-cs-turn="${i}" aria-current="${s.turn===i?'step':'false'}"`,t,s.turn===i)).join('')}</nav>${readonly?'':button('data-cs-keep','Keep this illustration',true)}<p id="cs-status" role="status" tabindex="-1">${esc(s.status)}</p><div class="cs-workspace${s.turn===1&&s.work.comparisonShown?' cs-compare-workspace':''}">${drawing(s.source,s.work.selectedIds)}${s.turn===1&&s.work.comparisonShown?drawing(s.source,s.source.parts.filter(p=>p.present).map(p=>p.id),true):''}<section class="cs-tray"><h3>${readonly?'Kept parts':'Add or remove parts'}</h3><p>Any combination, including an empty illustration, can be kept.</p>${s.source.parts.map(p=>{const chosen=s.work.selectedIds.includes(p.id);return `<div class="cs-part-row">${readonly?`<p><strong>${esc(p.label)}</strong> · ${chosen?'In my drawing':'Not in my drawing'}</p>`:button(`data-cs-part="${esc(p.id)}" aria-pressed="${chosen}"`,`${chosen?'Remove':'Add'} ${p.label}`,chosen)}${button(`data-cs-role="${esc(p.id)}" aria-label="Role: ${esc(p.label)}" aria-expanded="${s.role===p.id}"`,'Role')}</div>`;}).join('')}${role?`<section class="cs-role"><h4>${esc(role.label)}</h4><p>${esc(role.role)}</p></section>`:''}</section></div>${s.turn===1?(s.work.comparisonShown?comparison(s):readonly?'<p>Comparison was not shown on this kept sheet. Work on a copy to open it.</p>':button('data-cs-compare','Compare with source drawing')):''}<p>${esc(s.source.note)}</p>${teaching(s,readonly)}<p class="cs-notice">${esc(s.source.notice)}</p><p>${esc(s.source.microscopeNotice)}</p>`;}
function shelf(v){const view=cellModelsView(v.book),items=view.items,total=items.length;if(v.shelfPage===null){const last=[...items].reverse().find(x=>x.readable);v.shelfPage=Math.floor((last?.index??Math.max(0,total-1))/8);}v.shelfPage=Math.max(0,Math.min(v.shelfPage,Math.max(0,Math.ceil(total/8)-1)));const start=v.shelfPage*8;return `<h2 id="cs-title" tabindex="-1">Kept sheets</h2><p>Frozen illustrations and help choices, not scores.</p>${view.status==='unavailable'?'<p>This saved format cannot accept another sheet. Its original stays in your Notes download. Draft exploration is open.</p>':''}${total?`<p>Sheets ${start+1}–${Math.min(start+8,total)} of ${total}</p><ol class="cs-shelf" start="${start+1}">${items.slice(start,start+8).map(x=>`<li>${x.readable?button(`data-cs-card="${esc(x.id)}"`,`Sheet ${x.index+1} · ${x.raw.source.title}`):`<p>Sheet ${x.index+1} · unavailable here. Its original stays unchanged in your Notes download.</p>`}</li>`).join('')}</ol><div class="cs-actions">${button(`data-cs-page="-1"${start===0?' disabled':''}`,'Previous sheets')}${button(`data-cs-page="1"${start+8>=total?' disabled':''}`,'Next sheets')}</div>`:'<p>Keep an illustration to leave a sheet here. An unfinished drawing is welcome.</p>'}`;}
export function cellStudioPage(book,owner){const v=state(book,owner);if(v.mode==='legacy')return `<div data-cs-host>${button('data-cs-enter','Cell Studio')}${bodyCluesPage(book)}</div>`;let body;if(v.screen==='shelf')body=shelf(v);else if(v.screen==='card'){const x=cellModelsView(book).items.find(i=>i.id===v.card&&i.readable);if(x){if(!v.readonly.has(x.id))v.readonly.set(x.id,makeSlot(x.raw.source,x.raw.work));body=`<p class="cs-sheet-label">Sheet ${x.index+1}</p>`+activePage(v.readonly.get(x.id),true)+button('data-cs-copy',v.copies.has(x.id)?'Return to your copy':'Work on a copy');}else body='<h2 id="cs-title" tabindex="-1">This sheet is unavailable here</h2><p>Its original stays unchanged in your Notes download. Other sheets and drafts remain open.</p>';}else {if(!slot(v))draft(v,'leaf');body=activePage(slot(v));}return `<div class="cs-page" data-cs-root><header><div class="cs-actions">${button('data-cs-legacy','Back to Body clues')}${button('data-cs-draft','Return to illustration')}${button('data-cs-shelf','Kept sheets')}${button('data-cs-hear data-speak=""','Hear this page')}</div><h1>Cell Studio</h1><p>The town collection needs illustrations for future keepers.</p></header>${body}<details data-cs-chooser${v.chooser?' open':''}><summary>Choose another selected cell</summary><p>Each draft waits while you stay here.</p><div class="cs-actions">${cellCases.map(c=>button(`data-cs-case="${esc(c.id)}"`,c.title,v.active===c.id&&v.screen==='draft')).join('')}</div></details><p>Leaving or reloading loses drafts that have not been kept.</p></div>`;}
function visibleSpeech(root){function read(n){if(n.nodeType===3)return n.textContent+' ';if(n.nodeType!==1||n.matches('svg,[hidden],[aria-hidden="true"],.speech-controls'))return '';if(n.matches('button'))return n.matches('[data-cs-card],[data-cs-case]')?n.textContent+' ':n.matches('[data-cs-part]')?`${n.textContent.replace(/^(Add|Remove) /,'')}. ${n.getAttribute('aria-pressed')==='true'?'In my drawing':'Not in my drawing'}. `:'';if(n.tagName==='DETAILS'&&!n.open)return '';return [...n.childNodes].map(read).join(' ');}return read(root).replace(/\s+/g,' ').trim();}
export function bindCellStudio(book,ctx){const owner=()=>typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId,v=state(book,owner()),mode=v.mode,screen=v.screen,active=v.active,card=v.card,held=slot(v),heldSource=held?.source,rawSource=screen==='card'?cellModelsView(book).items.find(x=>x.id===card&&x.readable)?.raw.source:null;const root=document.querySelector(mode==='legacy'?'[data-cs-host]':'[data-cs-root]');if(!root)return;const live=n=>visit===v&&owner()===v.owner&&(typeof ctx.notebook==='function'?ctx.notebook():ctx.notebook)===book&&ctx.isActive()&&window.location.hash==='#living/bodies'&&root.isConnected&&n.isConnected&&v.mode===mode&&v.screen===screen&&v.active===active&&v.card===card&&(!(n.matches('[data-cs-turn],[data-cs-copy],[data-cs-part],[data-cs-role],[data-cs-compare],[data-cs-example],[data-cs-keep]')||(n.matches('[data-cs-hear]')&&held&&(screen!=='card'||rawSource)))||(slot(v)===held&&held?.source===heldSource&&(screen!=='card'||cellModelsView(book).items.some(x=>x.id===card&&x.readable&&x.raw.source===rawSource))));const guard=n=>['click','change','input','toggle'].forEach(type=>n.addEventListener(type,e=>{if(!live(n)){e.preventDefault();e.stopImmediatePropagation();}},{capture:true}));guard(root);root.querySelectorAll('button,select,input,textarea,details,[data-speak]').forEach(guard);const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();},redraw=(target='#cs-title')=>{ctx.render();ctx.focus(target);};const on=(sel,fn)=>root.querySelectorAll(sel).forEach(n=>n.addEventListener('click',()=>{if(!live(n)||n.disabled)return;stop();fn(n);}));if(mode==='legacy'){on('[data-cs-enter]',()=>{v.mode='studio';draft(v,'leaf');redraw();});bindBodyClues(book,{save:ctx.save,render:ctx.render,focus:ctx.focus});return;}
const attr=(name,value)=>`[${name}="${CSS.escape(value)}"]`,update=(action,value)=>{if(screen!=='draft')return;const s=slot(v),w=changeCellWork(s.source,s.work,action,value);if(w){s.work=w;s.status='';}};
on('[data-cs-legacy]',()=>{v.mode='legacy';redraw('[data-cs-enter]');});on('[data-cs-shelf]',()=>{v.screen='shelf';redraw();});on('[data-cs-draft]',()=>{v.screen='draft';if(!slot(v))draft(v,'leaf');redraw();});on('[data-cs-case]',n=>{draft(v,n.dataset.csCase);redraw();});on('[data-cs-card]',n=>{v.card=n.dataset.csCard;v.screen='card';redraw();});on('[data-cs-page]',n=>{v.shelfPage+=Number(n.dataset.csPage);redraw();});on('[data-cs-copy]',()=>{const x=cellModelsView(book).items.find(x=>x.id===v.card&&x.readable);if(!x)return;if(!v.copies.has(x.id))v.copies.set(x.id,makeSlot(x.raw.source,x.raw.work));v.active=x.id;v.screen='draft';redraw();});on('[data-cs-turn]',n=>{const s=slot(v);if(!s)return;s.turn=Number(n.dataset.csTurn);if(s.turn===1&&screen==='draft')update('compare');redraw();});on('[data-cs-compare]',()=>{update('compare');redraw();});on('[data-cs-part]',n=>{update('part',n.dataset.csPart);redraw(attr('data-cs-part',n.dataset.csPart));});on('[data-cs-role]',n=>{const s=slot(v);s.role=s.role===n.dataset.csRole?null:n.dataset.csRole;redraw(attr('data-cs-role',n.dataset.csRole));});on('[data-cs-example]',()=>{update('example');const s=slot(v);redraw(s.work.exampleSeen>=s.source.teaching.length?'[data-cs-keep]':'[data-cs-example]');});on('[data-cs-keep]',()=>{const s=slot(v);if(screen!=='draft'||!s)return;const id=keepCellModel(book,s.source,s.work,{canExport:ctx.canExport});if(!id){const view=cellModelsView(book);s.status=view.status==='unavailable'?'This saved format cannot accept another sheet. Its original stays unchanged in your Notes download. Your draft is still here.':!view.canKeep?'No new sheet number is available. Earlier sheets stay unchanged; this draft is still here.':'This illustration has not been kept. Earlier sheets stay unchanged in your Notes download. Your draft is still here for this visit.';}else{const saved=ctx.save();s.status=saved?.enabled===false?'This sheet is kept in this open page, but saving is off. Download Grown-up notes before closing to bring it back.':saved?.ok===false?'This sheet is kept in this open page, but device storage did not save. Download Grown-up notes before closing to bring it back.':'This illustration is kept. Find it in Kept sheets.';v.shelfPage=null;const kept=makeSlot(s.source,s.work);kept.turn=s.turn;kept.status=s.status;v.readonly.set(id,kept);v.card=id;v.screen='card';}redraw('#cs-status');});const chooser=root.querySelector('[data-cs-chooser]');chooser?.addEventListener('toggle',()=>{if(live(chooser)){stop();v.chooser=chooser.open;}});const hear=root.querySelector('[data-cs-hear]');hear?.addEventListener('click',()=>{if(live(hear))hear.dataset.speak=visibleSpeech(root);},{capture:true});}
export function cellPlantInvitation(book){const last=lastCellModel(book);if(!last)return `<section class="cs-plant"><h3>From whole plants to selected cells</h3><p>Make an illustration in <a data-cs-return href="#living/bodies">Body clues → Cell Studio</a>. ${cellModelsView(book).canKeep?'You can keep an unfinished sheet too.':'Local draft exploration is open. This saved collection cannot accept another sheet here.'}</p></section>`;const {raw,index}=last,s=raw.source,w=raw.work;return `<section class="cs-plant"><h3>Return to Sheet ${index+1} · ${esc(s.title)}</h3><p>Parts in this kept illustration: ${esc(w.selectedIds.map(id=>s.parts.find(p=>p.id===id)?.label).join(', ')||'No parts selected; this illustration is incomplete and empty')}.</p><p>${esc(s.note)}</p><p>${esc(s.notice)}</p><p>Our seedling drawings show whole plants. Can these pictures or stem lengths tell us whether a cell has chloroplasts? What further evidence would we need?</p><p>How does this selected source example help explain light use? Your illustration may differ from the reference.</p><details><summary>Frozen source reference, separate from your illustration</summary><p>${esc(s.context)}</p>${s.parts.map(p=>`<p><strong>${esc(p.label)}</strong> · ${p.present?'In this source example':'Not in this source example'}. ${esc(p.role)}</p>`).join('')}<p>${esc(s.microscopeNotice)}</p></details><p>Green leaf color hints at pigment in the leaf tissue, but these pictures cannot show which cells or parts hold it. Paler leaves do not mean there are no chloroplasts.</p><a data-cs-return href="#living/bodies">Body clues → Cell Studio → Kept sheets</a></section>`;}
